document.addEventListener('keydown',function(e){if(e.key==='F1'){e.preventDefault();window.open('/help','fleetops-help');}});
document.addEventListener('DOMContentLoaded',function(){const nav=document.createElement('nav');nav.setAttribute('aria-label','Documentation');nav.style.cssText='position:fixed;bottom:12px;right:16px;z-index:10000;background:#112b43;color:white;padding:9px 14px;border-radius:8px;font:14px system-ui;box-shadow:0 2px 8px #0005';nav.innerHTML='<a style="color:#8deaff;margin-right:16px" href="/help" target="fleetops-help">Help (F1)</a><a style="color:#8deaff" href="/about" target="fleetops-about">About FleetOps</a>';document.body.appendChild(nav);});
